import json
import re
import datetime
import html as _html
from zoneinfo import ZoneInfo

INBOX_PROMPT = (
    "You are triaging a healthcare clinic's unread inbox for the practitioner's morning brief. Using the practice's "
    "email tiers given, pick at most 5 emails that most need attention today, most urgent first. A cancellation or "
    "reschedule for an appointment in the next 48 hours, or a test result, is always urgent. Newsletters and "
    "marketing never make the list. For each, give the email's index from the input and one short reason it "
    "matters today. Never give clinical advice or interpretation."
)
INBOX_HINT = '{"priorities": [{"index": 0, "why": ""}]}'
HPM_LABELS = {"healthcare-practice-management", "cliniko-automations"}


def read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


def write_json(path, data):
    api.files.put(file=path, content=json.dumps(data, indent=2, sort_keys=True))


def parse_iso(iso):
    try:
        dt = datetime.datetime.fromisoformat(str(iso or "").replace("Z", "+00:00"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt
    except Exception:
        return None


def utc_iso(dt):
    return dt.astimezone(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def esc(s):
    return _html.escape(str(s or ""))


def list_appointments(q, per_page=100):
    try:
        result = api.connectors.invoke(
            server="cliniko-scheduling", tool="list_individual_appointments",
            args={"q": q, "sort": "starts_at:asc", "per_page": per_page},
        )
        return (result or {}).get("individual_appointments") or []
    except Exception:
        return []


practices = []
try:
    entries = api.files.list(path="PracticeManager/Practices", scope="org")
except Exception:
    entries = []
for entry in entries or []:
    fname = entry.get("name") if isinstance(entry, dict) else entry
    if not fname or not str(fname).endswith(".json"):
        continue
    practice = read_json("PracticeManager/Practices/" + fname, {}) or {}
    if practice.get("cliniko_business_id"):
        practices.append({"slug": str(fname)[:-5], "practice": practice})

# WorkQ is workspace-wide, so read it once: anything from this extension or cliniko-automations still open.
waiting = []
try:
    for row in api.workq.list(scope="org") or []:
        labels = set(row.get("labels") or [])
        if row.get("status") != "done" and labels & HPM_LABELS:
            waiting.append(row)
except Exception:
    waiting = []
referral_alerts = [w for w in waiting if "referral-watchdog" in (w.get("labels") or [])]

users_by_id = {}
try:
    for u in api.users.list() or []:
        users_by_id[str(u.get("id"))] = u
except Exception:
    users_by_id = {}

now = datetime.datetime.now(datetime.timezone.utc)
briefs = 0
for p in practices:
    slug, practice = p["slug"], p["practice"]
    business_id = str(practice["cliniko_business_id"])
    try:
        tz = ZoneInfo(practice.get("timezone") or "Australia/Sydney")
    except Exception:
        tz = datetime.timezone.utc
    local_now = now.astimezone(tz)
    day_start = local_now.replace(hour=0, minute=0, second=0, microsecond=0)
    day_end = day_start + datetime.timedelta(days=1)

    def fmt_time(iso):
        dt = parse_iso(iso)
        return dt.astimezone(tz).strftime("%I:%M %p").lstrip("0") if dt else ""

    def fmt_day_time(iso):
        dt = parse_iso(iso)
        return dt.astimezone(tz).strftime("%a %d %b, %I:%M %p").replace(" 0", " ") if dt else ""

    state_path = "PracticeManager/BriefState/" + slug + ".json"
    state = read_json(state_path, {}) or {}
    since = parse_iso(state.get("morning_at")) or (now - datetime.timedelta(hours=24))

    # 1. Today's diary
    today = [a for a in list_appointments(["business_id:=" + business_id, "starts_at:>=" + utc_iso(day_start), "starts_at:<" + utc_iso(day_end)])
             if not a.get("cancelled_at")]

    # 2. Changes since the last brief, for bookings in the next 14 days
    horizon = utc_iso(now + datetime.timedelta(days=14))
    new_bookings = [a for a in list_appointments(["business_id:=" + business_id, "created_at:>=" + utc_iso(since), "starts_at:>=" + utc_iso(now), "starts_at:<" + horizon], 50)
                    if not a.get("cancelled_at")]
    cancellations = []
    for a in list_appointments(["business_id:=" + business_id, "cancelled_at:*", "updated_at:>=" + utc_iso(since), "starts_at:>=" + utc_iso(now), "starts_at:<" + horizon], 50):
        c = parse_iso(a.get("cancelled_at"))
        if c and c >= since:
            cancellations.append(a)

    # 3. Inbox priorities (Outlook only - there is no Gmail read in this extension's automations yet)
    inbox_lines, inbox_note = [], ""
    if str(practice.get("email_provider") or "outlook") == "outlook":
        try:
            msgs = api.connectors.invoke(
                server="m365-mail-read", tool="list_emails",
                args={"folder": "inbox", "limit": 25, "unreadOnly": True, "receivedAfter": utc_iso(since)},
            )
            msgs = msgs if isinstance(msgs, list) else ((msgs or {}).get("value") or [])
        except Exception:
            msgs = []
            inbox_note = "Couldn't read the inbox this morning."
        if msgs:
            compact = [{
                "index": i, "from": (((m.get("from") or {}).get("emailAddress")) or {}).get("name") or "",
                "subject": m.get("subject") or "", "preview": (m.get("bodyPreview") or "")[:300],
            } for i, m in enumerate(msgs)]
            tiers = (practice.get("policy") or {}).get("email_tiers") or []
            try:
                ranked = api.ai.extract(prompt=INBOX_PROMPT, input=json.dumps({"tiers": tiers, "emails": compact}), schema_hint=INBOX_HINT)
            except Exception:
                ranked = {}
            for pr in ((ranked or {}).get("priorities") or [])[:5]:
                try:
                    m = msgs[int(pr.get("index"))]
                except Exception:
                    continue
                sender = (((m.get("from") or {}).get("emailAddress")) or {}).get("name") or ""
                inbox_lines.append({"text": sender + ": " + (m.get("subject") or "(no subject)"), "why": pr.get("why") or "", "link": m.get("webLink") or ""})
            if not inbox_lines:
                inbox_note = str(len(msgs)) + " unread since the last brief, none flagged as a priority."
        elif not inbox_note:
            inbox_note = "No unread email since the last brief."
    else:
        inbox_note = "Inbox not read: this practice uses Gmail, which the brief can't read yet."

    # 4. Yesterday's close-out loose ends
    last_closeout = state.get("closeout_summary") or {}

    # ---- compose
    sections = []
    diary = "".join("<li>" + esc(fmt_time(a.get("starts_at"))) + " - " + esc(a.get("patient_name") or "Patient") + "</li>" for a in today)
    sections.append("<h2>Today's diary (" + str(len(today)) + ")</h2>" + ("<ul>" + diary + "</ul>" if today else "<p>No appointments today.</p>"))

    changes = []
    for a in cancellations:
        changes.append("<li>Cancelled: " + esc(a.get("patient_name") or "Patient") + ", " + esc(fmt_day_time(a.get("starts_at"))) + "</li>")
    for a in new_bookings:
        changes.append("<li>New booking: " + esc(a.get("patient_name") or "Patient") + ", " + esc(fmt_day_time(a.get("starts_at"))) + "</li>")
    sections.append("<h2>Changes since the last brief</h2>" + ("<ul>" + "".join(changes) + "</ul>" if changes else "<p>No new bookings or cancellations in the next 14 days.</p>"))

    inbox_html = "".join(
        "<li>" + (("<a href='" + esc(l["link"]) + "'>" + esc(l["text"]) + "</a>") if l["link"] else esc(l["text"])) + " - " + esc(l["why"]) + "</li>"
        for l in inbox_lines
    )
    sections.append("<h2>Inbox priorities</h2>" + ("<ul>" + inbox_html + "</ul>" if inbox_lines else "") + ("<p>" + esc(inbox_note) + "</p>" if inbox_note else ""))

    waiting_html = "".join("<li>" + esc(w.get("title")) + "</li>" for w in waiting[:10])
    more = ("<p>... and " + str(len(waiting) - 10) + " more in WorkQ.</p>") if len(waiting) > 10 else ""
    sections.append("<h2>Waiting in WorkQ (" + str(len(waiting)) + ")</h2>" + ("<ul>" + waiting_html + "</ul>" + more if waiting else "<p>Nothing waiting.</p>"))
    if referral_alerts:
        sections.append("<h2>Referral alerts (" + str(len(referral_alerts)) + ")</h2><ul>" + "".join("<li>" + esc(w.get("title")) + "</li>" for w in referral_alerts) + "</ul>")

    if last_closeout:
        sections.append(
            "<h2>Left open at yesterday's close-out</h2><p>"
            + esc(str(last_closeout.get("missing_notes", 0)) + " appointment(s) without a finalised treatment note, "
                  + str(last_closeout.get("missing_invoices", 0)) + " without an invoice, "
                  + str(last_closeout.get("forms_incomplete", 0)) + " patient(s) with forms still incomplete.")
            + "</p>"
        )

    title = "Morning brief: " + (practice.get("name") or slug) + ", " + local_now.strftime("%a %d %b").replace(" 0", " ")
    page = (
        "<!doctype html><html><head><meta charset='utf-8'><title>" + esc(title) + "</title>"
        "<style>body{font:14px/1.5 system-ui,sans-serif;margin:24px;color:#1c2330}h1{font-size:20px}h2{font-size:16px;margin-top:20px}</style>"
        "</head><body><h1>" + esc(title) + "</h1>" + "".join(sections) + "</body></html>"
    )
    saved = api.artifacts.put(
        title=title, content=page, file_name="morning-brief-" + slug + "-" + local_now.strftime("%Y-%m-%d") + ".html",
        kind="document", mime_type="text/html", tags=["healthcare-practice-management", "daily-brief"],
    )
    url = (saved or {}).get("url") or ""
    headline = (str(len(today)) + " appointment(s) today, " + str(len(cancellations)) + " cancellation(s) and "
                + str(len(new_bookings)) + " new booking(s) since the last brief, " + str(len(waiting)) + " item(s) waiting in WorkQ.")

    recipients = [r for r in (practice.get("digest_recipient_ids") or [practice.get("reviewer_id")]) if r]
    if recipients:
        api.notify.send(title=title, body=(headline + " " + url).strip(), user_ids=recipients)
        if str(practice.get("email_provider") or "outlook") == "outlook":
            emails = [str((users_by_id.get(str(r)) or {}).get("email") or "") for r in recipients]
            emails = [e for e in emails if e]
            if emails:
                try:
                    api.connectors.invoke(
                        server="m365-mail-send", tool="send_email",
                        args={"to": emails, "subject": title, "body": page, "contentType": "HTML"},
                    )
                except Exception:
                    pass

    state["morning_at"] = utc_iso(now)
    write_json(state_path, state)
    briefs += 1

outcome = ("sent " + str(briefs) + " brief(s)") if briefs else "no_practices"
